const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:Number(v)%100===0?0:2}).format(Number(v||0)/100);
const icon=(name,size=19)=>{const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',orders:'M8 3h8v4H8z M6 5H4v16h16V5h-2 M8 12h8 M8 16h5',suppliers:'M4 21V7l8-4 8 4v14 M8 21v-7h8v7 M8 9h1 M15 9h1',lab:'M9 3h6 M10 3v6L4 19c-.5 1 .2 2 1.5 2h13c1.3 0 2-1 1.5-2L14 9V3 M8 14h8',actions:'M9 4H4v17h16V4h-5 M9 2h6v5H9z M8 12l2 2 5-5 M8 18h8',evidence:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',finance:'M4 4h16v16H4z M8 8h8 M8 12h3 M8 16h7',connections:'M8 5V2 M16 5V2 M6 5h12v5a6 6 0 0 1-12 0z M12 16v6',arrow:'M5 12h14 M13 6l6 6-6 6',search:'M10.5 18a7.5 7.5 0 1 1 0-15 7.5 7.5 0 0 1 0 15 M16 16l5 5',spark:'M12 2l2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z',link:'M10 13l4-4 M8 15l-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 6 0 M16 9l2-2a4 4 0 0 1 5 5l-5 5a4 4 0 0 1-6 0',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',check:'M5 12l4 4L19 6',box:'M3 7l9-5 9 5v10l-9 5-9-5z M3 7l9 5 9-5 M12 12v10',graph:'M5 5h4v4H5z M15 15h4v4h-4z M15 4h4v4h-4z M9 7h6 M7 9v8h8',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',close:'M5 5l14 14 M19 5L5 19',filter:'M3 5h18 M6 12h12 M9 19h6'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`};
const navItems=[['overview','Overview'],['orders','Customer promises'],['suppliers','Supplier network'],['lab','Recovery lab'],['actions','Action center'],['finance','Financial controls'],['evidence','Evidence & memory'],['connections','Data connections']];
let state={view:'overview',workspace:null,plan:null,candidate:null,overrides:{budget_minor:22500,inbound_units:80,disabled_suppliers:[]},busy:false,orderFilter:'all',orderSearch:'',supplierSearch:'',compare:[],projected:false,finance:null,cases:[],connections:null};
let toastTimer;
async function api(path,body){const r=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed.');return data}
function toast(text,error=false){$('toast').textContent=text;$('toast').className=error?'toast-error':'';$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5500)}
function badge(text,tone='neutral'){return `<span class="badge ${tone}">${esc(text)}</span>`}
function baseline(){return state.workspace.baseline}
function selectedSimulation(){if(!state.plan)return null;return state.candidate?state.plan.frontier.choices.find(c=>c.candidate_id===state.candidate):state.plan.selected_simulation||state.plan.simulation}
function currentOrders(){return state.projected&&selectedSimulation()?.orders?selectedSimulation().orders:baseline().orders}
function stale(){return state.plan&&JSON.stringify(state.plan.scenario_overrides)!==JSON.stringify(state.overrides)}
function header(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow"><span class="tiny-square"></span>${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="page-actions">${actions}</div></div>`}
function primary(text,action,disabled=false){return `<button class="button primary" data-action="${action}" ${disabled?'disabled':''}>${icon('spark',15)}${text}${icon('arrow',15)}</button>`}
function empty(title,text){return `<div class="empty-state">${icon('graph',32)}<h3>${title}</h3><p>${text}</p></div>`}
function renderNav(){const tasks=state.workspace?.history.actions.filter(a=>!a.done).length||0;$('nav').innerHTML=navItems.map(([id,label],i)=>`${i===4?'<div class="nav-divider"></div><p class="nav-label">CONTROL ROOM</p>':''}<button data-nav="${id}" aria-label="${label}" title="${label}" class="nav-item ${state.view===id?'selected':''}">${icon(id)}<span>${label}</span>${id==='actions'&&tasks?`<b>${tasks}</b>`:id==='lab'?'<span class="nav-ai">AI</span>':''}</button>`).join('');$('page-label').textContent=navItems.find(n=>n[0]===state.view)?.[1]||'Overview'}
function navigate(view){state.view=navItems.some(n=>n[0]===view)?view:'overview';location.hash=state.view;render();window.scrollTo({top:0,behavior:'smooth'})}
function stat(label,value,sub,klass='',extra=''){return `<article class="stat ${klass}"><div class="stat-label">${label}${extra||icon('arrow',15)}</div><div class="stat-value">${value}</div><p>${sub}</p></article>`}
function graph(){const data=state.workspace.data;const inv=data.inventory;const suppliers=[...new Set(data.supplier_offers.map(o=>o.supplier))];const orders=baseline().orders;let s='<svg class="dependency-graph" viewBox="0 0 840 440" role="group" aria-label="Supplier quotes connect to stock records and six customer promises"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#dce0df"/></pattern></defs><rect width="840" height="440" fill="url(#dots)"/><text x="25" y="30" class="graph-label">SUPPLIER SIGNALS</text><text x="305" y="30" class="graph-label">VERIFIED STOCK</text><text x="602" y="30" class="graph-label">CUSTOMER PROMISES</text>';
suppliers.forEach((supplier,i)=>{const y=95+i*130;data.supplier_offers.filter(o=>o.supplier===supplier).forEach(o=>{const j=inv.findIndex(v=>v.sku===o.sku);s+=`<path d="M205 ${y} C255 ${y},255 ${105+j*130},305 ${105+j*130}" class="graph-edge"/>`})});
orders.forEach((o,i)=>{const j=inv.findIndex(v=>v.sku===o.sku);s+=`<path d="M505 ${105+j*130} C550 ${105+j*130},550 ${65+i*66},595 ${65+i*66}" class="graph-edge ${o.short_units?'risk-edge':''}"/>`});
suppliers.forEach((supplier,i)=>{const y=67+i*130;const count=data.supplier_offers.filter(o=>o.supplier===supplier).length;s+=`<g class="graph-node" data-node="supplier:${esc(supplier)}" tabindex="0" role="button" aria-label="Inspect ${esc(supplier)}"><rect x="25" y="${y}" width="180" height="60" rx="10" class="supplier-node"/><rect x="37" y="${y+12}" width="34" height="34" rx="8" class="supplier-logo-bg logo-${i}"/><text x="54" y="${y+34}" text-anchor="middle" class="supplier-logo-letter">${supplier[0]}</text><text x="81" y="${y+24}" class="graph-title">${esc(supplier)}</text><text x="81" y="${y+42}" class="graph-subtitle">${count} quoted product lines</text></g>`});
inv.forEach((v,i)=>{const y=72+i*130;const demand=orders.filter(o=>o.sku===v.sku).reduce((a,o)=>a+o.quantity,0);const available=v.on_hand_units+v.verified_inbound_units;s+=`<g class="graph-node" data-node="inventory:${v.sku}" tabindex="0" role="button" aria-label="Inspect ${esc(v.product)} stock"><rect x="305" y="${y}" width="200" height="72" rx="10" class="inventory-node"/><circle cx="323" cy="${y+23}" r="4" class="risk-fill"/><text x="336" y="${y+27}" class="graph-title">${esc(v.product)}</text><text x="320" y="${y+49}" class="graph-number">${available}<tspan class="graph-subtitle"> / ${demand} units needed</tspan></text><text x="485" y="${y+49}" text-anchor="end" class="graph-gap">−${demand-available}</text></g>`});
orders.forEach((o,i)=>{const y=42+i*66;s+=`<g class="graph-node" data-node="order:${o.id}" tabindex="0" role="button" aria-label="Inspect ${esc(o.customer)}"><rect x="595" y="${y}" width="218" height="48" rx="8" class="order-node ${o.short_units?'order-node-risk':''}"/><text x="608" y="${y+19}" class="graph-title">${esc(o.customer)}</text><text x="608" y="${y+35}" class="graph-subtitle">${o.id} · due in ${o.due_hours}h</text><circle cx="798" cy="${y+24}" r="4" class="${o.short_units?'risk-fill':'good-fill'}"/></g>`});return s+'</svg>'}
function overview(){const b=baseline(),w=state.workspace,d=w.data,p=d.operating_policy[0],risk=b.orders.filter(o=>o.short_units),inv=d.inventory[0];return header('YOUR OPERATIONS, IN FOCUS','Protect every promise.','See what is at risk. Understand why. Find a recovery that actually holds.',`<span class="last-sync">${icon('clock',13)} Snapshot ${new Date(d.provenance.read_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span>${primary('Find a recovery','run-plan',state.busy)}`)+
`<div class="metrics-grid">${stat('CUSTOMER PROMISES',`${b.protected_orders}<span class="stat-denominator"> / ${b.total_orders}</span>`,'Supported by verified stock','',badge((b.total_orders-b.protected_orders)+' need attention','amber'))}${stat('REVENUE EXPOSED',money(b.revenue_at_risk_minor),'Value of units not supported by deadline','risk-stat')}${stat('RECOVERY BUDGET',money(b.budget_minor),'Incremental purchases · cash floor enforced')}${stat('SOURCE COVERAGE','7<span class="stat-denominator"> sources</span>','Orders, quotes, stock, invoices & policy','',badge(d.provenance.backend==='zetaris'?'Zetaris live':'Local mode',d.provenance.backend==='zetaris'?'green':'neutral'))}</div>
<div class="incident-strip"><span class="incident-icon">!</span><div><strong>A partial delivery has become a customer-promise problem.</strong><p>${inv.expected_inbound_units-inv.verified_inbound_units} filter units are missing from the expected receipt. Two other SKUs also need recovery.</p></div><button class="text-link" data-node="inventory:FILTER-01">Trace the evidence ${icon('arrow',15)}</button></div>
<div class="overview-grid"><section class="panel map-panel"><div class="panel-header"><div><span class="section-kicker">THE CONSEQUENCE MAP</span><h2>Your operation, connected.</h2><p>One missing fact can ripple across multiple commitments.</p></div><span class="map-status"><i></i> Source-backed</span></div><div class="graph-scroll">${graph()}</div><div class="map-footer"><span><i class="legend-dot green-dot"></i> Supported promise</span><span><i class="legend-dot orange-dot"></i> Evidence gap / shortage</span><span>${icon('search',12)} Click a node to inspect</span></div></section>
<aside class="panel mission-panel"><div class="mission-top"><span class="ai-tag">${icon('spark',12)} NEMOTRON MISSION</span><span class="mission-dots">•••</span></div><h2>Turn disruption<br>into a decision.</h2><p>Build a recovery that respects verified stock, available cash and promised time.</p><div class="mission-progress"><div><span>Current promise coverage</span><strong>${b.protected_orders}/${b.total_orders}</strong></div><progress value="${b.protected_orders}" max="${b.total_orders}"></progress></div><div class="risk-order-list">${risk.map(o=>`<button data-node="order:${o.id}"><span class="customer-mark">${o.customer[0]}</span><span><strong>${o.customer}</strong><small>${o.short_units} units short · due ${o.due_hours}h</small></span><span class="risk-amount">${money(o.revenue_at_risk_minor)}</span></button>`).join('')}</div>${primary(state.busy?'Evaluating…':'Build a verified plan','run-plan',state.busy)}<small class="mission-footnote">Proposed by Nemotron. Tested against constraints.</small></aside></div>
<div class="section-heading"><div><span class="section-kicker">EXPLORE THE ALTERNATIVES</span><h2>What changes the outcome?</h2></div><button class="text-link" data-nav="lab">Open Recovery lab ${icon('arrow',15)}</button></div><div class="playbook-grid"><button class="playbook" data-preset="supplier"><span class="playbook-icon coral">${icon('suppliers',23)}</span><span class="playbook-arrow">↗</span><h3>A supplier goes offline.</h3><p>Remove Harbor Supply and see which commitments can still be protected.</p><span class="playbook-tag">Availability stress test</span></button><button class="playbook" data-preset="cash"><span class="playbook-icon blue">${icon('finance',23)}</span><span class="playbook-arrow">↗</span><h3>Cash gets constrained.</h3><p>Limit recovery spend to $100. Compare what survives and what needs escalation.</p><span class="playbook-tag">Budget counterfactual</span></button><button class="playbook" data-preset="receipt"><span class="playbook-icon mint">${icon('box',23)}</span><span class="playbook-arrow">↗</span><h3>The receipt is corrected.</h3><p>Verify the missing inbound units and recompute the need for replacement stock.</p><span class="playbook-tag">New-evidence replan</span></button></div>`}
function ordersView(){const rows=currentOrders().filter(o=>(state.orderFilter==='all'||(state.orderFilter==='risk'?o.short_units>0:o.short_units===0))&&(o.customer+' '+o.id+' '+o.product).toLowerCase().includes(state.orderSearch.toLowerCase()));return header('PROMISE INTELLIGENCE','Every order has a dependency.','Inspect stock allocation, delivery deadlines and the consequences of a shortage.',primary('Find a recovery','run-plan',state.busy))+`<section class="panel"><div class="table-toolbar"><div class="segmented"><button data-order-filter="all" class="${state.orderFilter==='all'?'active':''}">All promises <b>6</b></button><button data-order-filter="risk" class="${state.orderFilter==='risk'?'active':''}">At risk</button><button data-order-filter="protected" class="${state.orderFilter==='protected'?'active':''}">Protected</button></div><div class="toolbar-right">${state.plan?`<label class="switch-label"><input type="checkbox" id="projected-toggle" ${state.projected?'checked':''}> Projected recovery</label>`:''}<input class="search-field" id="order-search" aria-label="Search customer orders" placeholder="Search orders…" value="${esc(state.orderSearch)}"></div></div>${state.projected?'<div class="info-strip">Projected scenario outcome. Purchases have not been executed.</div>':''}<div class="table-scroll"><table><thead><tr><th>Customer / promise</th><th>Product</th><th>Quantity covered</th><th>Deadline</th><th>Revenue at risk</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(o=>`<tr data-node="order:${o.id}"><td><div class="name-cell"><span class="customer-mark mark-${o.id.slice(-1)%3}">${o.customer[0]}</span><span><strong>${o.customer}</strong><small>${o.id} · ${o.destination}</small></span></div></td><td>${o.product}<small>${o.sku}</small></td><td><strong>${o.fulfilled_units}</strong><span class="muted"> / ${o.quantity}</span><progress value="${o.fulfilled_units}" max="${o.quantity}" class="table-progress ${o.short_units?'amber-progress':''}"></progress></td><td>${icon('clock',12)} ${o.due_hours}h<small>${o.priority} priority</small></td><td>${o.short_units?money(o.revenue_at_risk_minor):'—'}</td><td>${badge(o.short_units?'At risk':'Protected',o.short_units?'amber':'green')}</td><td>↗</td></tr>`).join('')||'<tr><td colspan="7" class="empty-cell">No matching orders.</td></tr>'}</tbody></table></div><div class="panel-bottom">${rows.length} promises · deadlines are relative to the disclosed scenario clock.<span>Quantities allocated once, in deadline order.</span></div></section>`}
function suppliersView(){const offers=state.workspace.data.supplier_offers;const names=[...new Set(offers.map(o=>o.supplier))].filter(n=>(n+' '+offers.find(o=>o.supplier===n).region).toLowerCase().includes(state.supplierSearch.toLowerCase()));return header('YOUR SUPPLY NETWORK','Match price, stock and time.','Compare stock, pack units and lead time against the promises you need to protect.',`<input class="search-field" id="supplier-search" placeholder="Find a supplier…" aria-label="Search suppliers" value="${esc(state.supplierSearch)}">`)+`<div class="supplier-intro"><span>${icon('evidence',17)} Source-backed quotes, not invented recommendations.</span><span>${offers.length} quotes · 3 suppliers · USD</span></div><div class="supplier-grid">${names.map((name,i)=>{const rows=offers.filter(o=>o.supplier===name),r=rows[0];return `<article class="panel supplier-card"><div class="supplier-card-top"><span class="supplier-avatar supplier-color-${i}">${name.split(' ').map(s=>s[0]).join('')}</span><label class="compare-check"><input type="checkbox" data-compare="${esc(name)}" ${state.compare.includes(name)?'checked':''}> Compare</label></div><h2>${name}</h2><p class="supplier-location">${r.region} · ${r.terms}</p><div class="supplier-facts"><div><small>Quoted lead time</small><strong>${Math.min(...rows.map(o=>o.lead_hours))}–${Math.max(...rows.map(o=>o.lead_hours))}h</strong></div><div><small>Scenario on-time history</small><strong>${r.on_time_shipments}/${r.total_shipments}</strong></div></div><div class="quote-list">${rows.map(o=>`<button data-node="offer:${o.id}"><span><strong>${state.workspace.data.inventory.find(v=>v.sku===o.sku)?.product||o.sku}</strong><small>${o.pack_units} per pack · ${o.available_packs} packs available</small></span><span><strong>${money(o.pack_price_minor/o.pack_units)}<small> / item</small></strong><small>${o.lead_hours}h arrival</small></span></button>`).join('')}</div><div class="supplier-card-bottom"><button class="text-link" data-node="supplier:${name}">Inspect quotes ↗</button><button class="subtle-button" data-exclude="${name}">Stress-test without supplier</button></div></article>`}).join('')}</div>${state.compare.length?`<section class="panel compare-panel"><div class="panel-header"><div><span class="section-kicker">SIDE BY SIDE</span><h2>Compare ${state.compare.length} suppliers</h2></div><button class="text-link" data-action="clear-compare">Clear selection</button></div><div class="table-scroll"><table><thead><tr><th>Product</th>${state.compare.map(n=>`<th>${esc(n)}</th>`).join('')}</tr></thead><tbody>${state.workspace.data.inventory.map(inv=>`<tr><td><strong>${inv.product}</strong></td>${state.compare.map(n=>{const o=offers.find(o=>o.supplier===n&&o.sku===inv.sku);return `<td>${o?`<strong>${money(o.pack_price_minor/o.pack_units)} / item</strong><small>${o.pack_units} / pack · ${money(o.pack_price_minor)} / pack</small><small>${o.lead_hours}h · ${o.available_packs*o.pack_units} units available</small>`:'No quote supplied'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div></section>`:''}`}
function scenarioControls(){const o=state.overrides;const suppliers=[...new Set(state.workspace.data.supplier_offers.map(s=>s.supplier))];return `<aside class="panel scenario-controls"><div class="panel-header"><div><span class="section-kicker">YOUR CONSTRAINTS</span><h2>Change the facts.</h2></div>${icon('filter',18)}</div><div class="control-group"><label for="budget-range">Recovery budget<strong id="budget-label">${money(o.budget_minor)}</strong></label><input id="budget-range" type="range" min="0" max="500" step="5" value="${o.budget_minor/100}"><div class="range-labels"><span>$0</span><span>$500</span></div><small>The cash floor remains enforced.</small></div><div class="control-group"><label for="inbound-range">Verified filter inbound<strong id="inbound-label">${o.inbound_units} units</strong></label><input id="inbound-range" type="range" min="0" max="120" step="20" value="${o.inbound_units}"><div class="range-labels"><span>0 units</span><span>120 expected</span></div><small>Scenario assumption, not a warehouse write.</small></div><div class="control-group"><label>Supplier availability</label><div class="supplier-toggles">${suppliers.map(n=>`<label><span><i class="availability-dot ${o.disabled_suppliers.includes(n)?'off':''}"></i>${n}</span><input type="checkbox" data-supplier-toggle="${n}" ${o.disabled_suppliers.includes(n)?'':'checked'}></label>`).join('')}</div></div><div class="control-divider"></div><div class="objective-card">${icon('evidence',17)}<div><strong>What the simulator enforces</strong><p>Pack sizes · quoted stock · delivery deadlines · purchase budget · cash floor · no double allocation.</p></div></div><button class="button primary full-width" data-action="run-plan" ${state.busy?'disabled':''}>${icon('spark',16)}${state.busy?'Evaluating…':'Evaluate with Nemotron'}${icon('arrow',15)}</button><button class="text-link reset-controls" data-action="reset-scenario">Reset scenario</button></aside>`}
function labView(){let p=state.plan,s=selectedSimulation(),f=p?.frontier,b=f?.baseline||baseline();const ready=s?.valid;let body='';if(state.busy)body=`<div class="panel planning-state"><div class="orbit-loader"><span>✳</span><i></i><i></i></div><span class="section-kicker">NVIDIA NEMOTRON IS PLANNING</span><h2>Finding a plan<br>that survives the facts.</h2><p>Reading source evidence, proposing supplier actions, and checking the consequences against stock, time and cash.</p><div class="planning-constraints"><span>Pack units</span><span>Delivery promises</span><span>Cash policy</span></div><small>Real provider requests. No pre-recorded answer.</small></div>`;
else if(!p)body=`<div class="panel lab-empty"><span class="lab-empty-mark">✳</span><span class="section-kicker">SIMULATE BEFORE YOU COMMIT</span><h2>A different fact.<br>An entirely different future.</h2><p>Change a supplier, tighten the budget, or correct a delivery count. Nemotron proposes the response. The simulator checks whether it works.</p><div class="lab-empty-chips"><span>01 · Interpret evidence</span><span>02 · Propose actions</span><span>03 · Verify consequences</span></div></div>`;
else body=`${stale()?'<div class="stale-banner">Controls changed. Evaluate again before drafting an action packet.</div>':''}<div class="plan-headline"><div><span class="section-kicker">${state.candidate?'SIMULATOR ALTERNATIVE':'NEMOTRON PROPOSAL'}</span><h2>${esc(state.candidate?'Compare a different recovery path.':p.display_headline||p.proposal.headline||'A plan, tested against your operation.')}</h2></div>${badge(s?.status==='ready'?'All promises supported':s?.valid?'Partial recovery':'Blocked',s?.status==='ready'?'green':s?.valid?'amber':'red')}</div><div class="plan-metrics">${stat('PROMISES PROTECTED',`${s?.protected_orders??'—'}<span class="stat-denominator"> / ${b.total_orders}</span>`,`${b.protected_orders} before recovery`)}${stat('INCREMENTAL SPEND',money(s?.cost_minor),`${money(s?.budget_minor)} cash-safe limit`)}${stat('REVENUE STILL EXPOSED',money(s?.revenue_at_risk_minor),s?.revenue_at_risk_minor===0?'All required units supported by deadline':'Some promises need escalation',s?.revenue_at_risk_minor?'risk-stat':'')}</div>
<section class="panel verified-plan"><div class="panel-header"><div><span class="section-kicker">THE ACTION GRAPH</span><h2>${s?.purchases?.length||0} supplier purchases. One checked outcome.</h2></div><span class="verification-label">${icon(ready?'check':'close',15)} ${ready?'Constraints passed':'Constraint failure'}</span></div>${!ready?`<div class="violation-list">${(s?.violations||[]).map(v=>`<p>! ${esc(v)}</p>`).join('')}</div>`:''}<div class="plan-purchases">${(s?.purchases||[]).map((a,i)=>`<div class="purchase-step"><span class="step-number">${String(i+1).padStart(2,'0')}</span><div class="purchase-main"><strong>${esc(a.supplier)}</strong><span>${esc(state.workspace.data.inventory.find(v=>v.sku===a.sku)?.product||a.sku)} · ${a.packs} packs × ${a.pack_units} units</span><small>Quote ${esc(a.quote_ref)} · ${esc(a.id)}</small></div><div class="purchase-time">${icon('clock',14)} ${a.lead_hours}h<small>quoted arrival</small></div><strong class="purchase-cost">${money(a.cost_minor)}</strong></div>`).join('')||'<div class="empty-cell">No purchase actions in this proposal.</div>'}</div><div class="outcome-strip"><span>${icon('evidence',15)} Drafts only. Source facts are rechecked before drafting.</span><button class="text-link" data-receipt="${p.id}">Inspect decision receipt ↗</button></div></section>
${f.minimum_full_recovery_minor!==null?`<div class="feasibility-note ${f.budget_gap_minor?'budget-gap':''}"><span>${icon(f.budget_gap_minor?'finance':'check',20)}</span><div><strong>${f.budget_gap_minor?`${money(f.budget_gap_minor)} more budget unlocks full recovery.`:`The lowest checked full recovery costs ${money(f.minimum_full_recovery_minor)}.`}</strong><p>${f.combinations_tested} non-dominated cross-product combinations checked for this bounded scenario. ${p.plan_quality==='best_checked'&&!state.candidate?'Nemotron matched the best checked outcome.':'Compare the alternatives below.'}</p></div></div>`:''}
<section class="panel reasoning-card"><div class="reasoning-icon">✳</div><div><span class="section-kicker">OPERATOR BRIEF · NIGHTSHIFT</span><p>${esc(state.candidate?'This simulator alternative has no separate generated briefing. Inspect its checked outcomes above.':p.operator_brief||'No briefing met the qualitative guidance checks for this run. Inspect the checked outcomes above.')}</p><div class="tradeoff-tags">${s?.valid?`<span>${money(s.budget_minor-s.cost_minor)} budget buffer</span><span>${s.purchases.length} source-backed quote lines</span><span>Quoted arrivals checked against deadlines</span>`:''}</div></div></section><div class="section-heading compact-heading"><div><h2>Different paths. Visible trade-offs.</h2><p>Simulator alternatives; these are not additional model-generated promises.</p></div></div><div class="alternatives">${f.choices.slice(0,4).map((c,i)=>`<button class="alternative ${state.candidate===c.candidate_id?'selected':''}" data-candidate="${c.candidate_id}"><span>${i===0?'Best checked':`Alternative ${i+1}`}</span><strong>${c.protected_orders}/${c.total_orders} promises</strong><p>${money(c.cost_minor)} spend · ${money(c.revenue_at_risk_minor)} exposed</p><small>${c.purchases.length} purchase drafts <span>↗</span></small></button>`).join('')}</div><div class="draft-bar"><div><strong>Ready for an operator to take it forward?</strong><p>Create persistent PO and customer-update drafts. Nothing is sent.</p></div><button class="button primary" data-action="draft-plan" ${!ready||!s?.purchases?.length||stale()||p.status==='drafted'?'disabled':''}>${icon('actions',16)}${p.status==='drafted'?'Packet drafted':'Draft action packet'}${icon('arrow',15)}</button></div>`;
return header('COUNTERFACTUAL RECOVERY','Change the facts. Test the future.','Proposed by Nemotron. Checked by code. Approved by an operator.',`<span class="sandbox-label">${icon('lab',14)} Scenario sandbox</span>`)+`${state.interpretation?`<div class="info-strip interpreted-note"><strong>From your note:</strong> ${esc(state.interpretation.interpretation)} ${Array.isArray(state.interpretation.questions)?state.interpretation.questions.map(esc).join(' '):''}<button class="text-link" data-receipt="${state.interpretation.run_id}">Inspect interpretation ↗</button></div>`:''}<section class="panel disruption-input"><div><span class="section-kicker">START WITH THE REAL-WORLD NOTE</span><h3>Describe what changed.</h3><p>Nemotron translates the note into proposed scenario controls. You can inspect and edit them before evaluation.</p></div><textarea id="disruption-note" aria-label="Describe the disruption" placeholder="Harbor is unavailable. Keep spend under $225. We have verified 80 inbound filter units." maxlength="3000"></textarea><button class="button secondary" data-action="interpret-note">${icon('spark',15)} Interpret with Nemotron</button></section><div class="lab-layout">${scenarioControls()}<div class="lab-results">${body}</div></div>`}
function actionsView(){const h=state.workspace.history,pending=h.actions.filter(a=>!a.done);return header('FROM DECISION TO FOLLOW-THROUGH','A plan is only the beginning.','Review the purchase drafts and customer updates created from approved scenario plans.',primary('Create another plan','go-lab'))+`<div class="action-summary"><div><strong>${pending.length}</strong><span>drafts awaiting review</span></div><div><strong>${h.actions.filter(a=>a.done).length}</strong><span>drafts marked reviewed</span></div><div><strong>0</strong><span>external actions sent</span></div></div><section class="panel"><div class="panel-header"><div><h2>Operator action queue</h2><p>Persistent local tasks. Marking reviewed does not send or execute a draft.</p></div>${badge('Sandbox','neutral')}</div>${h.actions.length?`<div class="action-list">${h.actions.map(a=>`<label class="action-row ${a.done?'completed':''}"><input type="checkbox" data-task="${esc(a.id)}" ${a.done?'checked':''}><div><strong>${esc(a.title)}</strong><p>${esc(a.detail)}</p><small>Plan ${a.plan_id.slice(0,8)} · ${a.done?'Reviewed locally':'Not sent'}</small></div>${badge(a.done?'Reviewed':'Draft',a.done?'green':'neutral')}</label>`).join('')}</div>`:empty('No drafts yet.','Evaluate a recovery, compare its consequences, then draft an action packet.')}<div class="panel-bottom">External purchases and messages require a separate operational integration and human authorization.</div></section><div class="section-heading"><h2>Decision history</h2></div><div class="history-grid">${h.plans.slice(0,6).map(p=>`<button class="panel history-card" data-open-plan="${p.id}"><div>${badge(p.status==='drafted'?'Drafted':'Proposed',p.status==='drafted'?'green':'neutral')}<small>${new Date(p.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</small></div><h3>${esc(p.display_headline||p.proposal.headline||'Recovery proposal')}</h3><p>${p.simulation.protected_orders??'—'}/${p.simulation.total_orders??6} promises · ${money(p.simulation.cost_minor)} incremental spend</p><span>Inspect decision →</span></button>`).join('')||'<p class="muted">Real model runs will appear here.</p>'}</div>`}
function financeView(){const r=state.finance;return header('SEMANTIC FINANCIAL CONTROLS','Reconcile meaning before money.','The underlying invoice engine still checks units, grain, price and delivery evidence.','<a class="button secondary" href="/review" target="_blank" rel="noopener">Technical workbench ↗</a>')+`<div class="finance-intro"><div><span class="section-kicker">ONE DISCREPANCY, MANY CONSEQUENCES</span><h2>A carton is not an item.<br>A repeated row is not another invoice.</h2><p>Inspect why a payment is held, resolve missing evidence, and preserve the reasoning behind each decision.</p></div><span>${icon('finance',60)}</span></div><section class="panel"><div class="table-toolbar"><select id="finance-case" aria-label="Select financial review scenario">${state.cases.map(c=>`<option value="${c.id}" ${c.id===(state.financeCase||'short-delivery')?'selected':''}>${esc(c.title)}</option>`).join('')}</select><button class="button primary" data-action="finance-run" ${state.financeBusy?'disabled':''}>${state.financeBusy?'<span class="mini-loader"></span> Reviewing…':`${icon('spark',15)} Run semantic audit`}</button></div>${r?`<div class="finance-result"><div class="plan-metrics">${stat('SUPPORTED PAYABLE',r.result.currency?money(r.result.payable_minor):'—','Verified by deterministic checks')}${stat('DECISION',r.result.status==='supported'?'Supported':'Held','No payment executed')}${stat('SOURCE MODE',r.source_info?.backend==='zetaris'?'Zetaris':'Local','Actual reads logged with the run')}</div><div class="finance-lines">${r.result.lines.map(l=>`<div><strong>${esc(l.id)}</strong>${badge(l.status,l.status==='supported'?'green':'amber')}<p>${l.issues.length?l.issues.map(esc).join(' '):'Unit conversion, identity, quantities, currency and price checks passed.'}</p></div>`).join('')}</div>${r.clarification?`<div class="clarification-box"><strong>${esc(r.clarification.question)}</strong><div><input id="clarify-pack" type="number" min="1" max="10000" placeholder="Confirmed items / carton"><button class="button secondary" data-action="finance-clarify">Record evidence & rerun</button></div><small>Use an operator-confirmed value. The correction is recorded; it does not rewrite the raw source.</small></div>`:''}<button class="text-link" data-receipt="${r.run_id}">Inspect real query and model receipts →</button></div>`:empty('Evidence before approval.','Select a scenario to run the real Nemotron semantic-contract workflow.')}</section>`}
function evidenceView(){const d=state.workspace.data,h=state.workspace.history;return header('INSPECTABLE BY DESIGN','Every decision leaves a trail.','Source evidence, model routes, policy checks and approved memory—kept distinct.',`<button class="button secondary" data-action="export-workspace">${icon('download',15)} Export snapshot</button>`)+`<div class="evidence-banner">${icon('evidence',28)}<div><strong>Proof, without pretending certainty.</strong><p>Receipts are a local hash chain, not independent signatures. Business records are synthetic. Source queries, model calls and local drafts are real.</p></div></div><div class="evidence-layout"><section class="panel"><div class="panel-header"><div><h2>Source lineage</h2><p>Operational datasets registered in the user's Zetaris instance.</p></div>${badge(d.provenance.backend,'green')}</div><div class="source-lineage">${Object.entries(d.provenance.tables).map(([name,table],i)=>`<button data-node="source:${name}"><span class="source-glyph source-color-${i}">${icon(i===0?'orders':i===1?'box':i===2?'suppliers':'evidence',19)}</span><div><strong>${name.replaceAll('_',' ')}</strong><small>${table}</small></div><span>${d[name].length} records</span>↗</button>`).join('')}<button data-action="go-finance"><span class="source-glyph">${icon('finance',19)}</span><div><strong>Purchase orders, invoices & deliveries</strong><small>Three additional sources · semantic financial controls</small></div>↗</button></div><div class="panel-bottom">Last actual read ${new Date(d.provenance.read_at).toLocaleString()}<button class="text-link" data-receipt="${d.provenance.source_run_id}">Query receipts ↗</button></div></section><section class="panel"><div class="panel-header"><div><h2>Operational memory</h2><p>Real Meterless H-MEM reference engine</p></div>${icon('evidence',18)}</div><div class="memory-explanation"><span class="memory-orbit">◎</span><h3>Remember the rule.<br>Recheck the facts.</h3><p>Drafting an approved plan stores supplier preferences and a constraint lesson. A future plan can recall that memory; current stock, quotes and deadlines are always revalidated.</p><div>${badge('Supplier preferences','neutral')}${badge('Source-revision scope','neutral')}${badge('No stored API keys','neutral')}</div><p class="memory-actual">${state.plan?.recalled_memory_id?`Current plan recalled ${esc(state.plan.recalled_memory_id)}.`:'No recalled operations memory reported for the selected plan.'}</p></div></section></div><div class="section-heading"><h2>Model-backed decisions</h2></div><div class="decision-log">${h.plans.map(p=>`<div><span class="decision-dot"></span><div><strong>${esc(p.display_headline||p.proposal.headline||'Recovery proposal')}</strong><small>${p.id.slice(0,12)} · ${p.elapsed_s}s · ${p.attempts?.length||1} proposal attempt(s)</small></div>${badge(p.simulation.valid?'Constraint checked':'Blocked',p.simulation.valid?'green':'red')}<button class="text-link" data-receipt="${p.id}">Inspect receipts ↗</button><button class="text-link" data-export-plan="${p.id}">Export ↓</button></div>`).join('')||empty('No decisions yet.','Run a recovery to inspect real model calls and their verification outcomes.')}</div>`}
function connectionsView(){const c=state.connections||{};return header('CONNECTED INTELLIGENCE','One workspace. Distinct responsibilities.','Credentials stay on the server. Each integration contributes an observable part of the workflow.')+`<div class="connections-grid">${[['Zetaris','Data federation','Seven registered sources, bounded read queries, and source-result hashes.','zetaris','Z'],['NVIDIA Nemotron','Interpretation & planning','Proposes typed semantic mappings and recovery actions; code checks the consequences.','nebius','N'],['Meterless Nightshift','Operator briefing','A real provider explains the checked result. Actual routed models are retained in receipts.','nightshift','M'],['Meterless H-MEM','Approved knowledge','Persistent scoped memory, backed by the upstream reference engine and trust ledger.','hmem','◎']].map(([name,role,text,key,letter])=>`<article class="panel connection-card"><div><span class="integration-logo">${letter}</span>${badge(c[key]?'Configured':'Setup needed',c[key]?'green':'amber')}</div><h2>${name}</h2><span class="connection-role">${role}</span><p>${text}</p>${['zetaris','nebius'].includes(key)?`<button class="button secondary" data-verify="${key}">Verify a real request ↗</button>`:'<span class="integration-note">Actual usage recorded with each applicable run</span>'}</article>`).join('')}</div><section class="panel source-notes"><h2>What this prototype does—and what remains a production integration.</h2><p>All commercial records are disclosed synthetic exports in private S3 storage. The workspace queries those records through Zetaris. It does not connect to a live ERP, place supplier orders, send customer messages or move money. Drafts and task state persist locally. The temporary S3 read session has an expiry; the setup script renews it.</p><p>The invoice mapping comparison tied at 13/13 on a small hold-heavy benchmark. That is evidence of tested cases, not proof of general business accuracy or an advantage over existing products.</p></section>`}
function render(){renderNav();if(!state.workspace)return;const views={overview,orders:ordersView,suppliers:suppliersView,lab:labView,actions:actionsView,finance:financeView,evidence:evidenceView,connections:connectionsView};$('main').innerHTML=views[state.view]();$('rail-source-status').textContent=state.workspace.data.provenance.backend==='zetaris'?'7 Zetaris sources connected':'Local scenario mode'}
async function runPlan(){if(state.busy)return;if(state.interpretation?.questions?.length){toast('Resolve the interpretation question by setting the budget control explicitly before evaluation.',true);return;}state.view='lab';location.hash='lab';state.busy=true;render();try{const p=await api('/api/plans',{overrides:state.overrides});state.plan=p;state.candidate=null;state.workspace=await api('/api/workspace');toast(p.simulation.valid?'Plan evaluated against stock, deadlines and cash.':'Plan blocked by a checked constraint.',!p.simulation.valid)}catch(e){toast(e.message,true)}finally{state.busy=false;render()}}
async function draftPlan(){if(!state.plan||stale())return;try{const r=await api('/api/plans/approve',{plan_id:state.plan.id,candidate_id:state.candidate});state.plan.status='drafted';if(r.history)state.workspace.history=r.history;else state.workspace=await api('/api/workspace');toast(r.memory_warning||'Action packet drafted locally. Nothing was sent.');navigate('actions')}catch(e){toast(e.message,true)}}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function sync(){try{$('refresh').classList.add('spinning');state.workspace=await api('/api/workspace/sync',{});render();toast('Source snapshot refreshed from Zetaris.')}catch(e){toast(e.message,true)}finally{$('refresh').classList.remove('spinning')}}
function openDetail(title,subtitle,body){$('detail-heading').innerHTML=`<span class="section-kicker">${esc(subtitle)}</span><h2>${esc(title)}</h2>`;$('detail-body').innerHTML=body;$('detail-dialog').showModal()}
function inspectNode(node){const type=node.split(':')[0],id=node.slice(type.length+1),d=state.workspace.data;
 if(type==='order'){const o=currentOrders().find(o=>o.id===id);if(!o)return;openDetail(o.customer,o.id,`<div class="detail-status">${badge(o.short_units?'At risk':'Supported',o.short_units?'amber':'green')}<span>${o.priority} priority · ${o.destination}</span></div><div class="detail-stats"><div><small>Required</small><strong>${o.quantity} units</strong></div><div><small>Supported</small><strong>${o.fulfilled_units} units</strong></div><div><small>Due in</small><strong>${o.due_hours}h</strong></div></div><h3>Where the units come from</h3>${o.allocations.map(a=>`<div class="detail-row"><strong>${a.source}</strong><span>${a.units} units · ${a.arrival_hours}h</span></div>`).join('')}${o.short_units?`<div class="stale-banner">${o.short_units} units lack support before the deadline. ${money(o.revenue_at_risk_minor)} of scenario revenue is exposed.</div>`:''}<h3>Source record</h3><pre>${esc(JSON.stringify(d.customer_orders.find(v=>v.id===id),null,2))}</pre>`)}
 if(type==='inventory'){const v=d.inventory.find(v=>v.sku===id);if(!v)return;openDetail(v.product,'STOCK EVIDENCE',`<div class="detail-stats"><div><small>On hand</small><strong>${v.on_hand_units}</strong></div><div><small>Verified inbound</small><strong>${v.verified_inbound_units}</strong></div><div><small>Expected inbound</small><strong>${v.expected_inbound_units}</strong></div></div><p>${esc(v.source_reference)}</p><h3>Dependent customer promises</h3>${baseline().orders.filter(o=>o.sku===id).map(o=>`<div class="detail-row"><strong>${o.customer}</strong><span>${o.quantity} units · ${o.due_hours}h</span></div>`).join('')}<h3>Source record</h3><pre>${esc(JSON.stringify(v,null,2))}</pre><button class="button primary" data-action="go-finance">${icon('finance',15)} Inspect financial discrepancy ↗</button>`)}
 if(type==='supplier'||type==='offer'){const offers=d.supplier_offers.filter(o=>type==='supplier'?o.supplier===id:o.id===id);if(!offers.length)return;openDetail(type==='supplier'?id:offers[0].quote_ref,'SUPPLIER QUOTE EVIDENCE',offers.map(o=>`<div class="detail-quote"><h3>${o.sku} · ${o.quote_ref}</h3><div class="detail-stats"><div><small>Pack</small><strong>${o.pack_units} units</strong></div><div><small>Price / pack</small><strong>${money(o.pack_price_minor)}</strong></div><div><small>Lead</small><strong>${o.lead_hours}h</strong></div></div><p>${o.available_packs} packs quoted available. Unit equivalent: ${money(o.pack_price_minor/o.pack_units)}.</p><pre>${esc(JSON.stringify(o,null,2))}</pre></div>`).join(''))}
 if(type==='source')openDetail(id.replaceAll('_',' '),d.provenance.tables[id],`<pre>${esc(JSON.stringify(d[id],null,2))}</pre>`)
}
async function inspectReceipt(id){openDetail('Decision receipt','REAL CALL METADATA','<div class="empty-cell">Loading receipt…</div>');try{const rows=await api('/api/receipts/'+id);$('detail-body').innerHTML=`<div class="receipt-summary">${badge(rows.length+' events','green')}<button class="text-link" data-download-receipts="${id}">Download JSON ↓</button></div>${rows.map(r=>`<details class="receipt-event"><summary><span class="receipt-event-dot"></span><strong>${r.kind.replaceAll('_',' ')}</strong><small>${new Date(r.at).toLocaleTimeString()}</small></summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details>`).join('')}`}catch(e){$('detail-body').textContent=e.message}}
function openCopilot(question){$('copilot').hidden=false;if(question){$('ask-input').value=question;submitQuestion()}else $('ask-input').focus()}
async function submitQuestion(){const question=$('ask-input').value.trim();if(!question||state.askBusy)return;state.askBusy=true;$('ask-input').value='';const body=$('copilot-body');body.querySelector('.copilot-intro')?.remove();const q=document.createElement('div');q.className='chat-question';q.textContent=question;body.append(q);const answer=document.createElement('div');answer.className='chat-answer';answer.textContent='Reading the current source snapshot…';body.append(answer);body.scrollTop=body.scrollHeight;try{const r=await api('/api/operations/ask',{question,overrides:state.view==='lab'?state.overrides:undefined});answer.textContent=r.answer;const receipt=document.createElement('button');receipt.className='text-link';receipt.textContent='Inspect model receipt ↗';receipt.dataset.receipt=r.run_id;answer.append(document.createElement('br'),receipt)}catch(e){answer.textContent=e.message}finally{state.askBusy=false;body.scrollTop=body.scrollHeight}}
function commandResults(){const q=$('command-input').value.toLowerCase();$('command-results').innerHTML=navItems.filter(n=>n[1].toLowerCase().includes(q)).map(([id,label])=>`<button data-nav="${id}">${icon(id)}<span>${label}</span>↵</button>`).join('')+($('command-input').value?`<button data-command-ask="${esc($('command-input').value)}">${icon('spark')}<span>Ask Nemotron: ${esc($('command-input').value)}</span>↗</button>`:'')}
function openCommand(){$('command-dialog').showModal();$('command-input').value='';commandResults();$('command-input').focus()}
async function financialReview(pack){if(state.financeBusy)return;state.financeBusy=true;render();try{const payload={case_id:state.financeCase||'short-delivery',mode:'agent'};if(pack!==undefined)payload.pack_override=pack;state.finance=await api('/api/review',payload)}catch(e){toast(e.message,true)}finally{state.financeBusy=false;render()}}
document.addEventListener('click',async event=>{const b=event.target.closest('button,[data-node],a[data-nav]');if(!b||b.disabled)return;try{
 if(b.dataset.nav){if($('command-dialog').open)$('command-dialog').close();navigate(b.dataset.nav)}
 if(b.dataset.node)inspectNode(b.dataset.node);
 if(b.dataset.receipt)await inspectReceipt(b.dataset.receipt);
 if(b.dataset.orderFilter){state.orderFilter=b.dataset.orderFilter;render()}
 if(b.dataset.exclude){state.interpretation=null;state.overrides.disabled_suppliers=[b.dataset.exclude];navigate('lab')}
 if(b.dataset.preset){state.interpretation=null;state.overrides={budget_minor:22500,inbound_units:80,disabled_suppliers:[]};if(b.dataset.preset==='supplier')state.overrides.disabled_suppliers=['Harbor Supply'];if(b.dataset.preset==='cash')state.overrides.budget_minor=10000;if(b.dataset.preset==='receipt')state.overrides.inbound_units=120;navigate('lab')}
 if(b.dataset.candidate){state.candidate=b.dataset.candidate;render()}
 if(b.dataset.openPlan){state.plan=await api('/api/plans/'+b.dataset.openPlan);state.overrides=state.plan.scenario_overrides;state.interpretation=null;state.candidate=null;navigate('lab')}
 if(b.dataset.exportPlan)download('unitshift-plan-'+b.dataset.exportPlan+'.json',await api('/api/plans/'+b.dataset.exportPlan));
 if(b.dataset.downloadReceipts)download('unitshift-receipts-'+b.dataset.downloadReceipts+'.json',await api('/api/receipts/'+b.dataset.downloadReceipts));
 if(b.dataset.ask)openCopilot(b.dataset.ask);
 if(b.dataset.commandAsk){$('command-dialog').close();openCopilot(b.dataset.commandAsk)}
 if(b.dataset.verify){b.disabled=true;await api('/api/preflight',{provider:b.dataset.verify});toast('Real '+b.dataset.verify+' request succeeded.');b.disabled=false}
 const action=b.dataset.action;
 if(action==='interpret-note'){const text=$('disruption-note').value;b.disabled=true;const r=await api('/api/operations/interpret',{text,overrides:state.overrides});state.overrides=r.overrides;state.interpretation=r;render();toast(r.interpretation+(Array.isArray(r.questions)&&r.questions.length?' '+r.questions.join(' '):''))}if(action==='run-plan')await runPlan();if(action==='draft-plan')await draftPlan();
 if(action==='go-lab'){if($('detail-dialog').open)$('detail-dialog').close();navigate('lab')}
 if(action==='go-finance'){if($('detail-dialog').open)$('detail-dialog').close();navigate('finance')}
 if(action==='reset-scenario'){state.interpretation=null;state.overrides={budget_minor:22500,inbound_units:80,disabled_suppliers:[]};render()}
 if(action==='clear-compare'){state.compare=[];render()}
 if(action==='export-workspace')download('unitshift-workspace.json',state.workspace);
 if(action==='finance-run')await financialReview();
 if(action==='finance-clarify'){const n=Number($('clarify-pack').value);if(!Number.isInteger(n)||n<1||n>10000)throw Error('Enter a confirmed integer pack size.');await financialReview(n)}
}catch(e){toast(e.message,true);if(b.dataset.verify)b.disabled=false}});
document.addEventListener('change',async event=>{const e=event.target;
 if(e.dataset.compare){state.compare=e.checked?[...new Set([...state.compare,e.dataset.compare])]:state.compare.filter(n=>n!==e.dataset.compare);render()}
 if(e.dataset.supplierToggle){state.overrides.disabled_suppliers=e.checked?state.overrides.disabled_suppliers.filter(n=>n!==e.dataset.supplierToggle):[...new Set([...state.overrides.disabled_suppliers,e.dataset.supplierToggle])];render()}
 if(e.id==='projected-toggle'){state.projected=e.checked;render()}
 if(e.id==='finance-case'){state.financeCase=e.value;state.finance=null;render()}
 if(e.dataset.task){try{state.workspace.history=await api('/api/actions/toggle',{action_id:e.dataset.task,done:e.checked});render()}catch(error){toast(error.message,true)}}
 if(e.id==='budget-range'||e.id==='inbound-range')render();
});
document.addEventListener('input',event=>{const e=event.target;if(e.id==='budget-range'){if(state.interpretation)state.interpretation.questions=[];state.overrides.budget_minor=Number(e.value)*100;$('budget-label').textContent=money(state.overrides.budget_minor)}if(e.id==='inbound-range'){state.overrides.inbound_units=Number(e.value);$('inbound-label').textContent=e.value+' units'}
 if(e.id==='order-search'){state.orderSearch=e.value;const pos=e.selectionStart;render();$('order-search').focus();$('order-search').setSelectionRange(pos,pos)}
 if(e.id==='supplier-search'){state.supplierSearch=e.value;const pos=e.selectionStart;render();$('supplier-search').focus();$('supplier-search').setSelectionRange(pos,pos)}
 if(e.id==='command-input')commandResults();});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openCommand()}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='j'){event.preventDefault();openCopilot()}if(event.key==='Escape')$('copilot').hidden=true;if((event.key==='Enter'||event.key===' ')&&event.target.dataset.node){event.preventDefault();inspectNode(event.target.dataset.node)}});
$('command-trigger').addEventListener('click',openCommand);$('command-close').addEventListener('click',()=>$('command-dialog').close());$('detail-close').addEventListener('click',()=>$('detail-dialog').close());$('refresh').addEventListener('click',sync);$('copilot-open').addEventListener('click',()=>openCopilot());$('copilot-close').addEventListener('click',()=>$('copilot').hidden=true);$('ask-form').addEventListener('submit',e=>{e.preventDefault();submitQuestion()});$('org-switch').addEventListener('click',()=>toast('Northline is the disclosed demonstration workspace. Multi-tenant accounts are not enabled.'));
async function init(){try{const [w,c,cases]=await Promise.all([api('/api/workspace'),api('/api/status'),api('/api/cases')]);state.workspace=w;state.connections=c;state.cases=cases;const hash=location.hash.slice(1);state.view=navItems.some(n=>n[0]===hash)?hash:'overview';if(w.history.plans.length){state.plan=w.history.plans[0];state.overrides=state.plan.scenario_overrides}render()}catch(e){$('main').innerHTML=`<div class="boot error-boot">${icon('connections',34)}<h2>Source access needs attention.</h2><p>${esc(e.message)}</p><button class="button secondary" id="retry-workspace">Retry actual source reads</button></div>`;$('retry-workspace').addEventListener('click',()=>location.reload())}}
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(navItems.some(n=>n[0]===view)&&view!==state.view){state.view=view;render()}});
init();
